/**
 * Temporary audit: find exported identifiers that are never referenced
 * anywhere else in the repo (excluding the file that declares them).
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = 'C:/Users/Acer/Desktop/copy';
const DIRS = ['client/src', 'server/src', 'shared', 'scripts'];

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    const s = statSync(p);
    if (s.isDirectory()) walk(p, out);
    else if (/\.(js|jsx|mjs|ts|tsx)$/.test(name)) out.push(p);
  }
  return out;
}

const files = DIRS.flatMap((d) => walk(join(ROOT, d)));
const contents = new Map(files.map((f) => [f, readFileSync(f, 'utf8')]));

const EXPORT_RE = [
  /export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/g,
  /export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)/g,
  /export\s+class\s+([A-Za-z_$][\w$]*)/g,
];

function exportedNames(src) {
  const names = new Set();
  for (const re of EXPORT_RE) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(src))) names.add(m[1]);
  }
  // export { a, b as c }
  const braceRe = /export\s*\{([^}]*)\}/g;
  let m;
  while ((m = braceRe.exec(src))) {
    for (const part of m[1].split(',')) {
      const t = part.trim();
      if (!t) continue;
      const as = t.split(/\s+as\s+/);
      names.add((as[1] || as[0]).trim());
    }
  }
  // export default
  return names;
}

const WORD = (n) => new RegExp(`\\b${n.replace(/[$]/g, '\\$')}\\b`, 'g');
const countIn = (src, re) => (src.match(re) || []).length;

const rows = [];
for (const [file, src] of contents) {
  const names = exportedNames(src);
  for (const name of names) {
    const re = WORD(name);
    const hits = [];
    for (const [other, otherSrc] of contents) {
      if (other === file) continue;
      const count = countIn(otherSrc, re);
      if (count) hits.push([relative(ROOT, other).replace(/\\/g, '/'), count]);
    }
    if (!hits.length) {
      rows.push({
        file: relative(ROOT, file).replace(/\\/g, '/'),
        name,
        internalUses: countIn(src, re) - 1,
      });
    }
  }
}

rows.sort((a, b) => a.file.localeCompare(b.file) || a.name.localeCompare(b.name));
console.log('EXPORTED SYMBOLS WITH ZERO EXTERNAL REFERENCES');
console.log('='.repeat(78));
for (const r of rows) {
  console.log(`${r.file.padEnd(46)} ${r.name.padEnd(24)} internal-uses=${r.internalUses}`);
}
console.log('='.repeat(78));
console.log(`${rows.length} total`);
